package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class ChangePlanningAcceptance {
 static String api(String id){return "/api/openservice/change_request/"+id+"/plan";}
 static Map<String,Object> get(WorkflowSupport h,String id)throws Exception{return ProblemInvestigationsAcceptance.result(h.get(api(id),auth("admin")));}
 static Map<String,Object> body(WorkflowSupport h,String id,boolean ready)throws Exception{var page=get(h,id);return map("revision",page.get("revision"),"record_revision",Integer.parseInt(object(page.get("change")).get("sys_mod_count").toString()),"implementation","Deploy reviewed version <script>","impact","Brief service restart","backout","Restore previous deployment","test","Verify health and critical flows","impact_score",5,"likelihood",3,"ready",ready);}
 static Map<String,Object> save(WorkflowSupport h,String id,Map<String,Object> body)throws Exception{return ProblemInvestigationsAcceptance.result(h.json("POST",api(id),body,auth("admin")));}
 static void patch(WorkflowSupport h,String id,Map<String,Object> body,int expected)throws Exception{var response=h.json("PATCH","/api/now/table/change_request/"+id,body,auth("admin"));assertEquals(expected,response.statusCode(),html(response));}
 static void run(WorkflowSupport h)throws Exception{
  h.account("ChangeReviewAgent","agent");
  String legacy=h.add("change_request").get("sys_id").toString();patch(h,legacy,map("state","review"),200);patch(h,legacy,map("state","approved"),200);patch(h,legacy,map("state","rejected"),409);
  String id=h.add("change_request").get("sys_id").toString();assertEquals(0,get(h,id).get("revision"));assertEquals(false,get(h,id).get("current"));
  var blank=body(h,id,false);for(String key:List.of("implementation","impact","backout","test"))blank.put(key," ");blank.put("impact_score",1);blank.put("likelihood",1);var drafted=save(h,id,blank);assertEquals(false,drafted.get("current"));assertEquals("low",object(drafted.get("plan")).get("risk"));patch(h,id,map("state","review"),409);
  var ready=body(h,id,true);var first=save(h,id,ready);assertEquals(true,first.get("current"));assertEquals(15,object(first.get("plan")).get("score"));assertEquals("high",object(first.get("change")).get("risk"));assertEquals("Deploy reviewed version <script>",object(first.get("change")).get("implementation_plan"));assertFalse(JSON.writeValueAsString(first).contains("snapshot"));assertEquals(409,h.json("POST",api(id),ready,auth("admin")).statusCode());
  patch(h,id,map("short_description","Changed context"),200);assertEquals(false,get(h,id).get("current"));patch(h,id,map("state","review"),409);var medium=body(h,id,true);medium.put("impact_score",2);medium.put("likelihood",3);assertEquals("medium",object(save(h,id,medium).get("plan")).get("risk"));patch(h,id,map("state","review"),200);assertEquals(true,get(h,id).get("current"));assertEquals(false,get(h,id).get("editable"));assertEquals(409,h.json("POST",api(id),body(h,id,true),auth("admin")).statusCode());patch(h,id,map("description","Unreviewed new impact"),409);
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.record(db,"change_request",id);object(item.get("data")).put("implementation_plan","Bypass");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,item)).status);assertEquals("Deploy reviewed version <script>",object(Service.record(db,"change_request",id).get("data")).get("implementation_plan"));}
  patch(h,id,map("state","approved"),200);Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"change_request");}var changed=new LinkedHashMap<>(original);changed.put("version",Approvals.version(original)+1);ReferencePickerAcceptance.writeSchema(h,"change_request",changed);patch(h,id,map("state","implement"),409);assertEquals(true,get(h,id).get("can_rework"));assertEquals(403,h.json("PATCH","/api/now/table/change_request/"+id,map("state","rejected"),auth("ChangeReviewAgent")).statusCode());patch(h,id,map("state","rejected"),200);ReferencePickerAcceptance.writeSchema(h,"change_request",original);assertEquals(true,get(h,id).get("editable"));var withdraw=body(h,id,false);withdraw.put("impact_score",1);withdraw.put("likelihood",5);assertEquals(false,save(h,id,withdraw).get("current"));patch(h,id,map("state","draft"),200);patch(h,id,map("state","review"),409);
  var low=body(h,id,true);low.put("impact_score",1);low.put("likelihood",5);assertEquals("low",object(save(h,id,low).get("plan")).get("risk"));new Store(h.environment);assertEquals(true,get(h,id).get("current"));for(String state:List.of("review","approved","implement","closed"))patch(h,id,map("state",state),200);assertEquals(true,get(h,id).get("current"));patch(h,id,map("state","rejected"),409);
  try(var db=h.store.open()){assertEquals(5,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='change.plan_saved'",id));}
  assertEquals(204,h.json("DELETE","/api/now/table/change_request/"+id,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_change_plan WHERE change_id=?",id));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  h.account("ChangeAgent","agent");h.account("ChangeReader","reader");h.account("ChangeRequester","requester");String id=h.add("change_request").get("sys_id").toString(),route=api(id);var valid=body(h,id,true);patch(h,id,map("state","implement"),409);String incident=h.add("incident").get("sys_id").toString();assertEquals(409,h.json("PATCH","/api/now/table/incident/"+incident,map("state","7"),auth("admin")).statusCode());assertEquals(200,h.json("PATCH","/api/now/table/incident/"+incident,map("state","2"),auth("admin")).statusCode());
  for(String user:List.of("ChangeReader","ChangeRequester")){assertEquals(403,h.get(route,auth(user)).statusCode());assertEquals(403,h.json("POST",route,valid,auth(user)).statusCode());}assertEquals(404,h.get(api("f".repeat(32)),auth("admin")).statusCode());
  assertEquals(405,h.json("PATCH",route,valid,auth("admin")).statusCode());assertEquals(400,h.get(route+"?unexpected=1",auth("admin")).statusCode());assertEquals(400,h.json("POST",route+"?x=1",valid,auth("admin")).statusCode());assertEquals(400,h.json("POST",route,map(),auth("admin")).statusCode());
  for(Object invalid:List.of("yes",1)){var bad=new LinkedHashMap<>(valid);bad.put("ready",invalid);assertEquals(400,h.json("POST",route,bad,auth("admin")).statusCode());}
  for(String key:List.of("implementation","impact","backout","test"))for(Object invalid:List.of(1,"x".repeat(4001)," ")){var bad=new LinkedHashMap<>(valid);bad.put(key,invalid);assertEquals(400,h.json("POST",route,bad,auth("admin")).statusCode());}
  for(String key:List.of("impact_score","likelihood"))for(Object invalid:List.of("2",0,6)){var bad=new LinkedHashMap<>(valid);bad.put(key,invalid);assertEquals(400,h.json("POST",route,bad,auth("admin")).statusCode());}
  for(String key:List.of("revision","record_revision")){var bad=new LinkedHashMap<>(valid);bad.put(key,1);assertEquals(409,h.json("POST",route,bad,auth("admin")).statusCode());}
  var form=new LinkedHashMap<>(valid);form.put("ready","yes");assertEquals(400,h.protectedForm("/record/change_request/"+id+"/plan",form,auth("admin")).statusCode());form.put("ready","true");form.put("impact_score","bad");assertEquals(400,h.protectedForm("/record/change_request/"+id+"/plan",form,auth("admin")).statusCode());
  Map<String,Object> original;String owner;try(var db=h.store.open()){original=Service.schema(db,"change_request");owner=RecordAccess.owner(db,"admin");}ProblemInvestigationsAcceptance.access(h,"change_request",id,"private",owner);assertEquals(404,h.get(route,auth("ChangeAgent")).statusCode());ProblemInvestigationsAcceptance.access(h,"change_request",id,"workspace","");
  for(String field:List.of("description","state","risk","implementation_plan")){var schema=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));schema.put("field_rules",map(field,map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"change_request",schema);try{assertEquals(403,h.get(route,auth("ChangeAgent")).statusCode());assertEquals(403,h.json("POST",route,valid,auth("ChangeAgent")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"change_request",original);}}
  var schema=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));schema.put("field_rules",map("risk",map("write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"change_request",schema);try{assertEquals(403,h.json("POST",route,valid,auth("ChangeAgent")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_change_plan"));assertEquals(0,((Number)Service.record(db,"change_request",id).get("revision")).intValue());}}finally{ReferencePickerAcceptance.writeSchema(h,"change_request",original);}
  valid=body(h,id,true);for(String key:List.of("implementation","impact","backout","test"))valid.put(key,"x".repeat(4000));valid.put("impact_score",5);valid.put("likelihood",5);var result=ProblemInvestigationsAcceptance.result(h.json("POST",route,valid,auth("ChangeAgent")));assertEquals(true,result.get("current"));assertEquals(25,object(result.get("plan")).get("score"));
  schema=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));schema.put("version",Approvals.version(original)+1);schema.put("transition_rules",map("approved",map("min_approvals",1)));ReferencePickerAcceptance.writeSchema(h,"change_request",schema);try{assertEquals(false,get(h,id).get("current"));patch(h,id,map("state","review"),409);save(h,id,body(h,id,true));patch(h,id,map("state","review"),200);patch(h,id,map("state","approved"),409);}finally{ReferencePickerAcceptance.writeSchema(h,"change_request",original);}
 }
}
